    "title": "中信证券：年内铜价有望站上16000美元/吨",
    "link": "https://36kr.com/newsflashes/3976860592238856?f=rss",
    "pub_date": "2026-09-10 08:31:47",
    "author": "",
    "description": "36氪获悉，中信证券研报称，上半年全球主要铜矿企业产量下滑近5%，极端天气和关键辅料的潜在扰动或致下半年产量延续下滑态势。供需改善趋势下，可预见的去库延续将强化铜价的交易弹性；后续若递增式关税落地，新一轮的高强度库存囤积有望助推年内铜价站上16000美元/吨。往更远看，中信证券预测中长期铜矿供应增速仅为2%—2.5%，不宜高估2028年—2029年的供应高峰，但应充分重视中资企业主导增产所带来的量增弹性及价值。",
