    "content": "9月9日，A股市场震荡，深证成指、创业板指、科创综指均高开低走。市场继续保持快速轮动的结构性行情，红利相关板块走强，前一个交易日走强的AI语料、短剧游戏等板块明显调整，整个A股市场超3600只股票下跌，近1800只股票上涨。A股市场成交额为1.87万亿元，较前一个交易日缩量，已连续3个交易日低于2万亿元。资金面上，场内资金激烈博弈。截至9月8日，9月以来A股融资余额减少超120亿元，股票型ETF资金净流入超50亿元。近期，A股市场连续震荡，各板块持续轮动。分析人士认为，在多方因素共同作用下，短期市场大概率维持区间震…"
