    "title": "杰富瑞据悉正逐步结束固定收益外包交易业务，负责人将离职",
    "link": "https://36kr.com/newsflashes/3976851698217220?f=rss",
    "pub_date": "2026-09-10 08:22:44",
    "author": "",
    "description": "杰富瑞金融集团正在逐步结束固定收益外包交易业务，退出这项仅在一年前还试图扩张的业务。据知情人士透露，杰富瑞固定收益外包交易主管Joram Siegel即将离职。这些知情人士因信息未公开而要求匿名。根据他的领英个人资料显示，他于2024年初加入杰富瑞，此前曾在Marex领导类似业务。杰富瑞一位发言人不愿置评。Siegel未回复置评请求。（新浪财经）",
    "content": "杰富瑞金融集团正在逐步结束固定收益外包交易业务，退出这项仅在一年前还试图扩张的业务。据知情人士透露，杰富瑞固定收益外包交易主管Joram Siegel即将离职。这些知情人士因信息未公开而要求匿名。根据他的领英个人资料显示，他于2024年初加入杰富瑞，此前曾在Marex领导类似业务。杰富瑞一位发言人不愿置评。Siegel未回复置评请求。（新浪财经）"
