    "content": "新华社德黑兰9月9日电 伊朗外交部副部长加里巴巴迪9日批评国际原子能机构理事会当天通过的由英国、法国、德国共同推动的伊核问题决议，该决议主张将相关伊核问题提交至联合国安理会。 加里巴巴迪在社交媒体上发文说，一些国家袭击伊朗受国际原子能机构保障监督的核设施、干扰正常核查进程，随后又以核查受阻为由，推动国际原子能机构理事会通过这项决议，这种做法既无法弥补有关国家政策和行动的失败，也无法在联合国安全理事会取得任何成果。 据伊朗伊斯兰共和国通讯社报道，伊朗驻国际原子能机构代表礼萨·纳杰菲在该机构理事会的会议上批评说，这项决…"
