    "content": "大象真的会“记仇”吗？ 两条河流，并没有筑起一道隔绝人象冲突的屏障。 “大象对水资源有极高的生理需求，河流并非阻隔大象的屏障，反而是其高频活动区。” 南方周末记者 刘佳伦 南方周末实习生 姜心悦 责任编辑：姚忆江 0\"> 尼泊尔奇特旺，一头大象正被锁链捆在太阳能电子栅栏内。图/视觉中国 14年前，野生公象“杜尔贝” （Dhurbey） 在尼泊尔奇特旺踩踏杀害了沙尼查拉·博特 （Shanichara Bote） 的双亲。 14年后，2026年7月5日凌晨，同一头象再次闯入博特的新家，当场夺走他的儿媳和年仅四岁幼孙的生…"
