    "author": "白涌泉",
    "description": "新华社苏瓦9月9日电（记者白涌泉）初抵斐济，记者便听到一句当地人常挂在嘴边的话：“我们是‘飞翔斐济人’。” 在外界印象中，太平洋岛国斐济碧海环礁、清波万里，当地人枕海而居、熟稔水性。初闻此言让记者心生疑惑，何谓“飞翔”？走近斐济人的生活，答案在记者的见闻中逐渐清晰。 “不能没有橄榄球” 5月的一天，斐济首都苏瓦市一家餐馆的服务员送给记者一份特别的礼物：一张面额7斐济元的纸币。在纸币图案中，一名男子手持橄榄球向前奔跑。 9月3日，在斐济首…",
    "content": "新华社苏瓦9月9日电（记者白涌泉）初抵斐济，记者便听到一句当地人常挂在嘴边的话：“我们是‘飞翔斐济人’。” 在外界印象中，太平洋岛国斐济碧海环礁、清波万里，当地人枕海而居、熟稔水性。初闻此言让记者心生疑惑，何谓“飞翔”？走近斐济人的生活，答案在记者的见闻中逐渐清晰。 “不能没有橄榄球” 5月的一天，斐济首都苏瓦市一家餐馆的服务员送给记者一份特别的礼物：一张面额7斐济元的纸币。在纸币图案中，一名男子手持橄榄球向前奔跑。 9月3日，在斐济首都苏瓦市，一名橄榄球爱好者展示一张面额7斐济元的纸币。新华社记者白涌泉摄 橄榄球…"
