    "title": "乌克兰苏梅市一购物中心遇袭致两人死亡",
    "link": "http://www.news.cn/20260910/ba654407425246548221f7b205ca62e2/c.html",
    "pub_date": "2026-09-10 07:33:00",
    "author": "李东旭",
    "description": "新华社基辅9月9日电（记者李东旭）乌克兰苏梅州军事行政长官奥列格·格里戈罗夫9日晚在社交媒体发文说，苏梅市一家购物中心当晚遭到无人机袭击，截至22时25分，袭击已造成至少两人死亡、20人受伤。 格里戈罗夫说，死者为一名21岁男子和一名21岁女子，伤者中有4人伤势严重。 近期，俄军对苏梅州的空袭持续升级。格里戈罗夫8日说，俄军当天对该州发动多次袭击，造成一人死亡、10人受伤。",
