    "content": "前不久，经典话剧《雷雨》再度回归北京人艺首都剧场。上演时，担任此次复排导演的杨立新度过他的69岁生日。2004年，饰演周朴园；22年后，担纲《雷雨》复排导演。角色变了，他的追求没有变——对传统的坚守和对戏剧的革新，一样都不能少。 晚上7点半，大戏开场。北京人民艺术剧院排练厅，聊起表演，杨立新滔滔不绝。 “老话儿说‘生书熟戏’——评书要听新的，听过的故事没意思；看戏要看老的，舞台上能保留下来的，大多是经典。观众看的是表演，台词、节奏，甚至微表情都有‘嚼头儿’。”在杨立新看来，“让经典保持原来的风格、味道、韵律，不能走…"
