    "content": "新华社大马士革9月9日电（记者林建杰）叙利亚过渡政府国防部9日晚发表声明说，叙西北部伊德利卜省一个用于存储武器和战争遗留物的临时仓库当天发生爆炸，造成14名过渡政府国防部人员死亡，另有包括平民在内的10余人受伤。 声明说，过渡政府国防部在爆炸发生后立即与相关部门协调，控制现场并予以处理。相关部门仍在调查事故原因。 声明说，过渡政府国防部对这起事件承担全部责任，向遇难者致哀，愿伤者早日康复。 总部设在英国的“叙利亚人权观察组织”说，该武器库靠近难民营和居民区，当时周边民众听到多次连续爆炸声。爆炸造成周边地区大范围财产…"
