    "description": "“公司规定扣掉以后就退这么多。”深圳市某驾校工作人员在微信中回复万女士。万女士给某驾校交了4000元报名费，申请退费却被扣除近2000元，而她连方向盘都没摸过，实在无法接受扣费结果，万女士由此开启了维权之路。",
    "content": "“公司规定扣掉以后就退这么多。”深圳市某驾校工作人员在微信中回复万女士。万女士给某驾校交了4000元报名费，申请退费却被扣除近2000元，而她连方向盘都没摸过，实在无法接受扣费结果，万女士由此开启了维权之路。"
