    "content": "09/09/2026 - 23:16 路透社称，一家韩国卫星影像分析机构周三（9月9日）表示，朝鲜连接中国的鸭绿江跨境大桥工程已接近完工。这座名为“新鸭绿江大桥”的桥梁横跨鸭绿江，这条河流也是中朝两国的天然边界。大桥计划连接中国东北部城市丹东的自由贸易区与朝鲜新义州市。因此，这意味着这座全长约3公里、始建于2010年代初的跨境公路桥梁可能即将正式启用。 中国一侧的桥梁工程早在2014年就已经完工，但此后整个项目一直处于停滞状态。 近几个月来，朝鲜一侧施工明显加快。当前也正值中国自2025年底以来努力修复与朝鲜关系之…"
