    "content": "09/09/2026 - 23:31 美国总统特朗普周三（9月9日）预测，美国与伊朗之间的战争将在今年11月美国中期选举结束后“立即”结束。他还表示，由于伊朗战争而大幅上涨的油价，可能要到美国中期选举之后才会回落。 特朗普在“空军一号”前接受采访时说：“我认为，这场战争将在选举结束后立即结束。因为他们已经撑不下去了。他们拼命想要影响这场选举，这样我们就能选出一批软弱的人，让他们不再管伊朗，让他们拥有核武器。” 随后他还称：“我们并没有在推动谈判。是的，谈判有可能发生，但这并不是我们目前正在考虑的事情。这场战争将在我…"
