    "title": "国际原子能机构将伊朗核问题提交联合国安理会，系20年来首次，中国投反对票 - RFI - 法国国际广播电台",
    "link": "https://www.rfi.fr/cn/%E6%94%BF%E6%B2%BB/20260909-%E5%9B%BD%E9%99%85%E5%8E%9F%E5%AD%90%E8%83%BD%E6%9C%BA%E6%9E%84%E5%B0%86%E4%BC%8A%E6%9C%97%E6%A0%B8%E9%97%AE%E9%A2%98%E6%8F%90%E4%BA%A4%E8%81%94%E5%90%88%E5%9B%BD%E5%AE%89%E7%90%86%E4%BC%9A%EF%BC%8C%E7%B3%BB20%E5%B9%B4%E6%9D%A5%E9%A6%96%E6%AC%A1%EF%BC%8C%E4%B8%AD%E5%9B%BD%E6%8A%95%E5%8F%8D%E5%AF%B9%E7%A5%A8",
    "pub_date": "2026-09-10 03:45:03",
    "author": "",
    "description": "09/09/2026 - 21:36 联合国核监督机构国际原子能机构（IAEA）理事会周三(9月9日)决定将伊朗问题提交联合国安全理事会。这是20年来伊朗首次因未能配合一项持续多年的调查而被提交安理会。此次调查涉及核查人员在伊朗一些未申报地点发现的铀元素痕迹。西方官员怀疑，这些痕迹可能证明伊朗在2003年之前曾秘密实施核武器计划。伊朗则表示，它并未寻求发展核武器，其核计划完全出于和平目的。 将伊朗问题提交安理会意味着伊朗可能面临制裁和资…",
    "content": "09/09/2026 - 21:36 联合国核监督机构国际原子能机构（IAEA）理事会周三(9月9日)决定将伊朗问题提交联合国安全理事会。这是20年来伊朗首次因未能配合一项持续多年的调查而被提交安理会。此次调查涉及核查人员在伊朗一些未申报地点发现的铀元素痕迹。西方官员怀疑，这些痕迹可能证明伊朗在2003年之前曾秘密实施核武器计划。伊朗则表示，它并未寻求发展核武器，其核计划完全出于和平目的。 将伊朗问题提交安理会意味着伊朗可能面临制裁和资产冻结。不过，这类惩罚措施不太可能真正实施，因为伊朗的盟友俄罗斯和中国拥有安理会…"
