    "content": "新华社北京9月9日电（记者阳娜）北京市9日正式发布的《北京“十五五”时期高精尖产业发展规划》明确，大力推动产业智能化升级，2026年规模以上制造业企业全面实现数字化达标，到2030年规模以上生产企业全部达到基础级智能工厂标准，建设1000家先进级智能工厂、100家卓越级和领航级智能工厂。 “北京将推进人工智能赋能新型工业化，深入实施‘人工智能+制造’，推动人工智能深度嵌入全行业、全环节，大力发展新一代智能制造。”北京市经信局规划处副处长都康表示，当前北京规上制造业企业数字化达标率为95%，为实现规划目标，将通过引导…"
