    "author": "牛润哲",
    "description": "新华社武汉9月9日电 记者手记：当传统民俗走上赛场 新华社记者牛润哲 在旱地上“划船”、用高脚杆奔跑、持铜铃做健身操……鄂西群山之间，湖北省第十一届少数民族传统体育运动会热烈上演。 来自汉族、土家族、苗族、侗族等多个民族的近2800名湖北运动员组成29支代表队，齐聚恩施土家族苗族自治州宣恩县，在这座武陵山城开启了一场竞技、民俗和欢乐交织的盛会。 与常见运动会不同，这一运动会的竞赛项目大多源自传统民俗。从乡野地头走向竞技赛场，古老习俗得到…",
    "content": "新华社武汉9月9日电 记者手记：当传统民俗走上赛场 新华社记者牛润哲 在旱地上“划船”、用高脚杆奔跑、持铜铃做健身操……鄂西群山之间，湖北省第十一届少数民族传统体育运动会热烈上演。 来自汉族、土家族、苗族、侗族等多个民族的近2800名湖北运动员组成29支代表队，齐聚恩施土家族苗族自治州宣恩县，在这座武陵山城开启了一场竞技、民俗和欢乐交织的盛会。 与常见运动会不同，这一运动会的竞赛项目大多源自传统民俗。从乡野地头走向竞技赛场，古老习俗得到创造性转化、创新性发展，让泥土里的记忆重新“活”了起来，也让山民的游戏被更多人看…"
