    "description": "新华社巴格达9月9日电（记者李军）伊拉克交通部9日发表声明说，一艘悬挂巴拿马国旗的油轮当天清晨在伊拉克领海内遭不明来源袭击，导致船体受损，但未造成人员伤亡或燃油泄漏。 声明说，袭击发生在9日5时30分许，事发油轮由伊拉克油轮公司租用，用于储存燃油。事发后，伊拉克安全、海事等部门对涉事船只实施持续监控，并对周边海域开展排查，确保不发生油品泄漏或其他可能威胁航行安全与海洋环境的隐患。 声明表示，相关部门正就具体情况、袭击来源及原因展开调查。",
