    "author": "",
    "description": "中新网北京9月9日电 (记者 孙自法)中国科学院青藏高原研究所陈发虎院士领衔的古生态与人类适应团队联合中外合作者，最近通过对云南鹤庆蝙蝠洞遗址开展多学科综合研究，首次系统揭示中国南方丹尼索瓦人(丹人)的体质形态、技术行为与生存策略，重建出这一神秘人群在青藏高原东南缘的生存全景图，包括石器技术保持长期稳定、生存适应高度务实等。",
